#include <Arduino.h>

/*
 * The driver does the phase sequence: the sketch sends a pulse and a
 * direction, and the chip works out which windings to energise.
 */
const byte STEP_PIN = 2;
const byte DIR_PIN = 3;
const byte ENABLE_PIN = 4;
const byte RESET_PIN = 5;
const byte SLEEP_PIN = 6;

unsigned long count = 0;
long steps = 0;

void setup() {
  Serial.begin(9600);
  pinMode(STEP_PIN, OUTPUT);
  pinMode(DIR_PIN, OUTPUT);
  pinMode(ENABLE_PIN, OUTPUT);
  pinMode(RESET_PIN, OUTPUT);
  pinMode(SLEEP_PIN, OUTPUT);

  /*
   * The enable, reset and sleep lines are all active low, so a running
   * chip holds the enable line down and the other two up.
   */
  digitalWrite(ENABLE_PIN, LOW);
  digitalWrite(RESET_PIN, HIGH);
  digitalWrite(SLEEP_PIN, HIGH);

  // The microstep pins low are the chip's full-step setting.
  pinMode(7, OUTPUT);
  pinMode(8, OUTPUT);
  pinMode(9, OUTPUT);
  digitalWrite(7, LOW);
  digitalWrite(8, LOW);
  digitalWrite(9, LOW);

  Serial.println("motor ready");
}

void loop() {
  // Twenty steps one way, then twenty the other. The count is what the
  // sketch has sent; the steps are what the shaft has net of them.
  if ((count % 40) < 20) {
    digitalWrite(DIR_PIN, HIGH);
    steps += 1;
  } else {
    digitalWrite(DIR_PIN, LOW);
    steps -= 1;
  }
  count += 1;

  // The pulse the driver counts.
  digitalWrite(STEP_PIN, HIGH);
  delay(2);
  digitalWrite(STEP_PIN, LOW);
  delay(60);

  Serial.print("step ");
  Serial.println(steps);
}

#include <Arduino.h>

/*
 * The MS pins pick 1/16 step. The translator still does the phase sequence;
 * the difference is that one pulse moves the shaft a sixteenth of a step,
 * and the coil currents follow the chip's sine table between the full-step
 * positions.
 */
const byte STEP_PIN = 2;
const byte DIR_PIN = 3;
const byte ENABLE_PIN = 4;
const byte RESET_PIN = 5;
const byte SLEEP_PIN = 6;
const byte MS1_PIN = 7;
const byte MS2_PIN = 8;
const byte MS3_PIN = 9;

void setup() {
  Serial.begin(9600);
  pinMode(STEP_PIN, OUTPUT);
  pinMode(DIR_PIN, OUTPUT);
  pinMode(ENABLE_PIN, OUTPUT);
  pinMode(RESET_PIN, OUTPUT);
  pinMode(SLEEP_PIN, OUTPUT);
  pinMode(MS1_PIN, OUTPUT);
  pinMode(MS2_PIN, OUTPUT);
  pinMode(MS3_PIN, OUTPUT);

  digitalWrite(ENABLE_PIN, LOW);
  digitalWrite(RESET_PIN, HIGH);
  digitalWrite(SLEEP_PIN, HIGH);
  digitalWrite(MS1_PIN, HIGH);
  digitalWrite(MS2_PIN, HIGH);
  digitalWrite(MS3_PIN, HIGH);

  Serial.println("microstep ready");
  // Let the driver settle at home before the first pulse, so the bench sees
  // the reference state the pulses move away from.
  delay(100);
}

void loop() {
  // Sixteen sixteenths are one full step, 7.5 degrees.
  digitalWrite(DIR_PIN, HIGH);
  for (byte i = 0; i < 16; i++) {
    digitalWrite(STEP_PIN, HIGH);
    delay(2);
    digitalWrite(STEP_PIN, LOW);
    delay(60);
  }
  Serial.println("microstep 16");

  // And sixteen back return the shaft to where it started.
  digitalWrite(DIR_PIN, LOW);
  for (byte i = 0; i < 16; i++) {
    digitalWrite(STEP_PIN, HIGH);
    delay(2);
    digitalWrite(STEP_PIN, LOW);
    delay(60);
  }
  Serial.println("microstep 0");

  delay(500);
}

#include <Arduino.h>
#include <Wire.h>

/*
 * The board has run out of pins, so the expander makes eight more out of
 * the two on the I2C bus. The byte names the output register, and the byte
 * after it says what the ports should be.
 */
const byte EXPANDER = 0x20;
const byte OUTPUT_REGISTER = 0x00;

byte counter = 0;

void setup() {
  Serial.begin(9600);
  Wire.begin();
  Serial.println("expander ready");
}

void loop() {
  // The counter in binary: bit 0 is the first light.
  Wire.beginTransmission(EXPANDER);
  Wire.write(OUTPUT_REGISTER);
  Wire.write(counter);
  Wire.endTransmission();

  Serial.print("count ");
  Serial.println(counter);
  counter += 1;
  delay(500);
}

#include <Arduino.h>
#include <Wire.h>

/*
 * Two ports, sixteen lights. The chip powers up with every pin an input,
 * so the first job is to clear both direction registers. After that the
 * pair of output latches is one sixteen-bit number.
 */
const byte EXPANDER = 0x20;
const byte IODIR_A = 0x00;
const byte IODIR_B = 0x01;
const byte GPIO_A = 0x12;
const byte GPIO_B = 0x13;

unsigned int counter = 0;

void writeRegister(byte address, byte value) {
  Wire.beginTransmission(EXPANDER);
  Wire.write(address);
  Wire.write(value);
  Wire.endTransmission();
}

void setup() {
  Serial.begin(9600);
  Wire.begin();

  // Direction bits at zero make the pins outputs.
  writeRegister(IODIR_A, 0x00);
  writeRegister(IODIR_B, 0x00);
  Serial.println("expander ready");
}

void loop() {
  // The counter in binary, low byte on port A and high byte on port B.
  writeRegister(GPIO_A, counter & 0xFF);
  writeRegister(GPIO_B, counter >> 8);

  Serial.print("count ");
  Serial.println(counter);
  counter += 1;
  delay(500);
}

#include <Arduino.h>
#include <Wire.h>

/*
 * Sixteen pins on two wires, and one more wire for the interrupt.
 *
 * The sketch tells the expander which port to watch and then leaves: the
 * chip samples PA0 itself and pulls INTA low when it moves. That turns a
 * decision the sketch would have to poll for into a level it can read with
 * one digitalRead.
 *
 * The pull-up is the chip's own, switched on with GPPU, so the button only
 * has to connect the port to ground. It is switched on and allowed to settle,
 * and the port is read once before the pin is watched: that read is the level
 * the chip compares against, and a pin coming up is an edge too.
 */
const byte EXPANDER = 0x20;
const byte IODIR_A = 0x00;
const byte INTCON_A = 0x08;
const byte GPPU_A = 0x0C;
const byte GPIO_A = 0x12;
const byte GPINTEN_A = 0x04;
const int INTA_PIN = 2;
const int LED_PIN = 8;

byte readRegister(byte address) {
  Wire.beginTransmission(EXPANDER);
  Wire.write(address);
  Wire.endTransmission();
  Wire.requestFrom(EXPANDER, 1);
  return Wire.available() ? Wire.read() : 0;
}

void writeRegister(byte address, byte value) {
  Wire.beginTransmission(EXPANDER);
  Wire.write(address);
  Wire.write(value);
  Wire.endTransmission();
}

void setup() {
  Serial.begin(9600);
  pinMode(INTA_PIN, INPUT);
  pinMode(LED_PIN, OUTPUT);
  Wire.begin();

  writeRegister(IODIR_A, 0xFF);   // PA0 is an input
  writeRegister(INTCON_A, 0x00);  // any change is an interrupt
  writeRegister(GPPU_A, 0x01);    // the chip supplies the pull-up
  delay(10);
  readRegister(GPIO_A);           // the read is the level it compares against
  writeRegister(GPINTEN_A, 0x01); // now watch PA0

  Serial.println("watching PA0");
}

void loop() {
  // One read of one pin, instead of a bus transaction per pass.
  if (digitalRead(INTA_PIN) == LOW) {
    // Reading the port clears the flag and says which way the button went.
    byte port = readRegister(GPIO_A);
    if ((port & 0x01) == 0) {
      digitalWrite(LED_PIN, HIGH);
      Serial.println("pressed");
    } else {
      digitalWrite(LED_PIN, LOW);
      Serial.println("released");
    }
  }
  delay(5);
}

#include <Arduino.h>
#include <Wire.h>

/*
 * One chip, sixteen lights, sixteen duties. The chip powers up asleep, and
 * PRESCALE is writable only while it sleeps: the sketch writes the prescaler
 * for a 50 Hz frame, wakes the oscillator, then gives channel n a duty of
 * (n + 1) / 16. The last channel uses the full-on bit in ON_H rather than a
 * width, because a 4096-count high time does not fit in twelve bits.
 */
const byte DRIVER = 0x40;
const byte MODE1 = 0x00;
const byte MODE2 = 0x01;
const byte LED0_ON_L = 0x06;
const byte PRESCALE = 0xFE;

const byte SLEEP = 0x10;
const byte AI = 0x20;
const byte FULL = 0x10;

void writeRegister(byte address, byte value) {
  Wire.beginTransmission(DRIVER);
  Wire.write(address);
  Wire.write(value);
  Wire.endTransmission();
}

void setPwm(byte channel, unsigned int on, unsigned int off) {
  Wire.beginTransmission(DRIVER);
  Wire.write(LED0_ON_L + channel * 4);
  Wire.write(on & 0xFF);            // ON_L
  Wire.write(on >= 4096 ? FULL : (on >> 8) & 0x0F);
  Wire.write(off & 0xFF);           // OFF_L
  Wire.write(off >= 4096 ? FULL : (off >> 8) & 0x0F);
  Wire.endTransmission();
}

void setup() {
  Serial.begin(9600);
  Wire.begin();

  writeRegister(MODE2, 0x04);       // totem-pole outputs
  writeRegister(MODE1, SLEEP | AI); // stop the oscillator, enable auto-increment
  writeRegister(PRESCALE, 121);     // 25 MHz / (4096 * 122) is about 50 Hz
  writeRegister(MODE1, AI);         // wake it up

  for (byte channel = 0; channel < 15; channel++) {
    setPwm(channel, 0, (channel + 1) * 256);
  }
  setPwm(15, 4096, 0);              // the last light is full on, not a width
  Serial.println("sixteen levels");
}

void loop() {
  Serial.print("levels");
  for (byte channel = 0; channel < 16; channel++) {
    Serial.print(" ");
    Serial.print(channel + 1);
  }
  Serial.println();
  delay(1000);
}

#include <Arduino.h>
#include <Wire.h>

/*
 * The DS3231 keeps the DS1307's time registers, so the seven bytes below
 * are the same BCD packing. What it adds is a status register: bit 7 says
 * the oscillator stopped, which means the time cannot be trusted until a
 * sketch sets it. The same chip has a thermometer at 0x11 and 0x12.
 */
const byte CLOCK = 0x68;
const byte STATUS = 0x0F;
const int LED_PIN = 9;

byte toBcd(byte value) {
  return ((value / 10) << 4) | (value % 10);
}

byte fromBcd(byte value) {
  return (value >> 4) * 10 + (value & 0x0F);
}

byte readRegister(byte address) {
  Wire.beginTransmission(CLOCK);
  Wire.write(address);
  Wire.endTransmission();
  Wire.requestFrom(CLOCK, 1);
  return Wire.available() ? Wire.read() : 0;
}

void writeRegister(byte address, byte value) {
  Wire.beginTransmission(CLOCK);
  Wire.write(address);
  Wire.write(value);
  Wire.endTransmission();
}

void setClock() {
  Wire.beginTransmission(CLOCK);
  Wire.write(0x00);
  Wire.write(toBcd(0));   // seconds
  Wire.write(toBcd(30));  // minutes
  Wire.write(toBcd(9));   // hours
  Wire.write(toBcd(6));   // Saturday
  Wire.write(toBcd(24));  // date
  Wire.write(toBcd(10));  // October
  Wire.write(toBcd(26));  // 2026
  Wire.endTransmission();
}

void reportTime() {
  Wire.beginTransmission(CLOCK);
  Wire.write(0x00);
  Wire.endTransmission();
  Wire.requestFrom(CLOCK, 7);
  byte second = fromBcd(Wire.read() & 0x7F);
  byte minute = fromBcd(Wire.read() & 0x7F);
  byte hour = fromBcd(Wire.read() & 0x3F);
  Wire.read();  // weekday, not printed
  byte date = fromBcd(Wire.read() & 0x3F);
  byte month = fromBcd(Wire.read() & 0x1F);
  byte year = fromBcd(Wire.read());

  Serial.print("time 20");
  Serial.print(year);
  Serial.print(month);
  Serial.print(date);
  Serial.print(" ");
  Serial.print(hour);
  Serial.print(":");
  Serial.print(minute);
  Serial.print(":");
  Serial.println(second);
}

void setup() {
  Serial.begin(9600);
  pinMode(LED_PIN, OUTPUT);
  Wire.begin();

  // A clock that lost power says so until the time is written.
  if (readRegister(STATUS) & 0x80) {
    Serial.println("lost power");
    setClock();
    writeRegister(STATUS, 0x00);
    Serial.println("clock set");
  } else {
    Serial.println("clock running");
  }

  reportTime();
  int raw = (readRegister(0x11) * 256) + readRegister(0x12);
  Serial.print("celsius ");
  Serial.println((raw >> 6) * 0.25);
}

void loop() {
  // The seconds bit toggles the light, once per second.
  byte second = readRegister(0x00) & 0x7F;
  if (second & 1) {
    digitalWrite(LED_PIN, HIGH);
  } else {
    digitalWrite(LED_PIN, LOW);
  }
  delay(200);
}

#include <Arduino.h>
#include <SPI.h>

/*
 * The chip reads the probe and hands the reading out as sixteen bits: four
 * status bits and a temperature in quarter-degree steps. The sketch shifts
 * out a dummy byte and takes the answer as it comes back.
 */
const byte CHIP_SELECT = 10;

void setup() {
  Serial.begin(9600);
  pinMode(CHIP_SELECT, OUTPUT);
  digitalWrite(CHIP_SELECT, LOW);
  SPI.begin();
  Serial.println("thermocouple ready");
}

void loop() {
  digitalWrite(CHIP_SELECT, LOW);
  SPI.begin();
  unsigned int high = SPI.transfer(0x00);
  unsigned int low = SPI.transfer(0x00);
  SPI.end();
  digitalWrite(CHIP_SELECT, HIGH);

  // The status bits come off the top, and what is left is the temperature
  // in quarter-degree steps.
  float celsius = (((high << 8) | low) >> 3) * 0.25;
  Serial.print("celsius ");
  Serial.println(celsius);
  delay(500);
}

#include <Arduino.h>
#include <Wire.h>

/*
 * The converter takes twelve bits and holds a voltage between the ground
 * and the supply. The board reads that voltage back on an analog pin, so
 * the loop closes on the bench rather than in the log.
 */
const byte CONVERTER = 0x60;

void setup() {
  Serial.begin(9600);
  Wire.begin();
  Serial.println("converter ready");
}

void loop() {
  // A ramp: the output walks from the ground to the supply.
  for (int code = 0; code < 4096; code += 256) {
    Wire.beginTransmission(CONVERTER);
    Wire.write(code >> 8);
    Wire.write(code & 0xFF);
    Wire.endTransmission();
    delay(100);

    Serial.print("code ");
    Serial.print(code);
    Serial.print(" reads ");
    Serial.println(analogRead(A0));
  }
}

#include <Arduino.h>
#include <Wire.h>

/*
 * The memory takes an address and then the bytes at it. Reading is the
 * same shape: name the address, and then read.
 */
const byte MEMORY = 0x50;
const int COUNTER = 0x0010;

void setup() {
  Serial.begin(9600);
  Wire.begin();
  Serial.println("memory ready");
}

void loop() {
  // Read the counter back.
  Wire.beginTransmission(MEMORY);
  Wire.write(COUNTER >> 8);
  Wire.write(COUNTER & 0xFF);
  Wire.endTransmission();
  Wire.requestFrom(MEMORY, 1);
  byte count = Wire.read();

  // Count it up and write it back.
  count = count + 1;
  Wire.beginTransmission(MEMORY);
  Wire.write(COUNTER >> 8);
  Wire.write(COUNTER & 0xFF);
  Wire.write(count);
  Wire.endTransmission();

  Serial.print("count ");
  Serial.println(count);
  delay(500);
}

#include <Arduino.h>

// Chip select is an ordinary pin; the module's clock and data in are the
// SPI bus's own wires, so the sketch never touches them.
const byte CS = 10;

void writeRegister(byte reg, byte value) {
  SPI.begin();
  SPI.transfer(reg);
  SPI.transfer(value);
  SPI.end();
}

void drawHeart(int small) {
  // DIGIT1..DIGIT8 are the columns, left to right, and bit 0 of each is the
  // top row: 0b00111111 is a column lit from the top down to row 5.
  writeRegister(1, small ? 0x00 : 0x0E);
  writeRegister(2, 0x3F);
  writeRegister(3, 0x7F);
  writeRegister(4, 0xFE);
  writeRegister(5, 0xFE);
  writeRegister(6, 0x7E);
  writeRegister(7, 0x3F);
  writeRegister(8, small ? 0x00 : 0x0E);
}

void setup() {
  Serial.begin(115200);
  pinMode(CS, OUTPUT);
  digitalWrite(CS, HIGH);
  // The chip powers up shut down at its dimmest: wake it, then turn it up.
  writeRegister(0x0C, 0x01);
  writeRegister(0x0A, 0x0F);
  writeRegister(0x0B, 0x07);
  Serial.println("heartbeat");
}

void loop() {
  drawHeart(0);
  delay(180);
  drawHeart(1);
  delay(120);
  drawHeart(0);
  delay(180);
  drawHeart(1);
  delay(500);
}

#include <Arduino.h>

// The module as it is sold: an 84x48 glass with a PCD8544 behind it, and
// eight pins along the bottom. Four of them carry the picture -- clock, data
// in, chip select and the line that says whether a byte is a command or
// display memory -- and the rest are the reset line, the supply and the
// backlight, which this sketch leaves alone.
const byte PIN_SCK = 13;
const byte PIN_MOSI = 11;
const byte PIN_CS = 10;
const byte PIN_DC = 9;
const byte PIN_RST = 8;

const int WIDTH = 84;
const int BANKS = 6;

double phase = 0.0;

// A command byte. The data/command line is low, so the chip reads it as an
// instruction rather than as a byte of display memory. The transaction is
// already open: chip select stays low across a command and the memory bytes
// that follow it.
void sendCommand(byte value) {
  SPI.transfer(value, 0);
}

// A byte of display memory. The data/command line is high.
void sendData(byte value) {
  SPI.transfer(value, 1);
}

// The column address: the X command, with the column in its low bits.
void setColumn(int column) {
  sendCommand(0x80 | column);
}

// The bank address: the Y command, with the bank in its low bits.
void setBank(int bank) {
  sendCommand(0x40 | bank);
}

void setup() {
  Serial.begin(115200);
  pinMode(PIN_CS, OUTPUT);
  pinMode(PIN_DC, OUTPUT);
  pinMode(PIN_MOSI, OUTPUT);
  pinMode(PIN_SCK, OUTPUT);
  pinMode(PIN_RST, OUTPUT);

  // The reset line, low and then high again. The panel comes up in the state
  // a reset leaves it in, so this is all the module sees at power-up.
  digitalWrite(PIN_RST, LOW);
  delay(10);
  digitalWrite(PIN_RST, HIGH);
  delay(50);

  SPI.begin();

  // The extended instruction set, where the contrast voltage lives.
  SPI.beginTransaction();
  sendCommand(0x21);
  sendCommand(0xBF);
  // Back to the basic set: the address commands are only there.
  sendCommand(0x20);
  // Display on, and not inverted.
  sendCommand(0x0C);
  SPI.end();

  Serial.println("nokia 5110 wave");
}

void loop() {
  // Clear the glass: six banks of eighty-four columns, one byte each.
  for (int bank = 0; bank < BANKS; bank++) {
    SPI.beginTransaction();
    setBank(bank);
    setColumn(0);
    for (int x = 0; x < WIDTH; x++) {
      sendData(0);
    }
    SPI.end();
  }

  // The wave: one lit pixel per column, on the row the sine is at.
  for (int x = 0; x < WIDTH; x++) {
    double offset = 20.0 * sin(x * 0.12 + phase);
    // Truncation towards zero, which is what a cast to int does.
    int y = 23 + (offset < 0.0 ? ceil(offset) : floor(offset));
    SPI.beginTransaction();
    setColumn(x);
    setBank(y >> 3);
    sendData(1 << (y & 7));
    SPI.end();
  }

  phase = phase + 0.2;
  delay(30);
}

#include <Arduino.h>

byte BTN = 2;
byte LED = 8;

byte raw = HIGH;
byte settled = HIGH;
unsigned long changedAt = 0;

unsigned long DEBOUNCE_MS = 25;

byte state = 0;
unsigned long t0 = 0;
unsigned long waitMs = 0;

void setup() {
  pinMode(BTN, INPUT_PULLUP);
  pinMode(LED, OUTPUT);
  Serial.begin(115200);
  Serial.println("press to arm");
}

void loop() {
  unsigned long now = millis();

  byte level = digitalRead(BTN);
  if (level != raw) { raw = level; changedAt = now; }
  if (level != settled && now - changedAt >= DEBOUNCE_MS) {
    settled = level;
    if (settled == LOW) {
      if (state == 0) {
        state = 1;
      } else if (state == 2) {
        Serial.println("false start");
        digitalWrite(LED, LOW);
        state = 0;
        Serial.println("press to arm");
      } else if (state == 3) {
        Serial.print("latency ");
        Serial.print(now - t0);
        Serial.println(" ms");
        digitalWrite(LED, LOW);
        state = 4;
      }
    } else {
      if (state == 1) {
        state = 2;
        t0 = now;
        waitMs = 2000 + (now % 3000);
      } else if (state == 4) {
        state = 0;
        Serial.println("press to arm");
      }
    }
  }

  if (state == 2 && now - t0 >= waitMs) {
    state = 3;
    t0 = now;
    digitalWrite(LED, HIGH);
  }
}

#include <WiFi.h>

#define BLACK 0x0000
#define WHITE 0xFFFF
#define GREEN 0x07E0
#define SKY   0x867D

/*
 * The board keeps time only as well as it can count milliseconds, and that
 * counter starts at zero every time it resets. A clock that says 4,000 ms is
 * not telling the time; it is telling you how long it has been running. So the
 * time comes from the network, and the sketch's job is to ask for it.
 */
void setup() {
  Serial.begin(115200);
  tft.begin();
  tft.setRotation(1);
  tft.clear();
  tft.print("NOESIS BENCH NETWORK", 20, 20, SKY);

  /*
   * Joining is not instant, and it is not guaranteed: a real board spends
   * seconds here and a wrong password spends them for nothing. Polling the
   * status is the loop every ESP32 sketch in the world starts with.
   */
  WiFi.begin("noesis-bench", "benchwifi");
  while (WiFi.status() != WL_CONNECTED) {
    delay(50);
  }

  Serial.print("joined ");
  Serial.println(WiFi.localIP());
  tft.print("ip", 20, 60, SKY);
  tft.print(WiFi.localIP(), 90, 60, WHITE);
}

void loop() {
  /*
   * One request at a time, and none of them instant.
   *
   * net.get() says whether the answer has arrived; it does not wait for it,
   * because the firmware cannot wait for anything without stopping the rest of
   * the sketch. This loop is the difference between code that uses a network
   * and code that draws a picture, and it is the same loop the map lesson
   * teaches.
   */
  net.reset();
  while (net.get("http://api.noesis/time") == 0) {
    delay(20);
  }

  tft.fillRect(20, 120, 440, 40, BLACK);
  if (net.failed()) {
    Serial.println("network failed");
    tft.print("no answer from the network", 20, 120, 0xF800);
  } else {
    Serial.println(net.read());
    tft.print(net.read(), 20, 120, GREEN);
  }
  delay(1000);
}

#include <WiFi.h>

#define BLACK 0x0000
#define WHITE 0xFFFF
#define GREEN 0x07E0
#define SKY   0x867D

void setup() {
  Serial.begin(115200);
  tft.begin();
  tft.setRotation(1);
  tft.clear();
  tft.print("SENSOR FEED", 20, 20, SKY);

  WiFi.begin("noesis-bench", "benchwifi");
  while (WiFi.status() != WL_CONNECTED) {
    delay(50);
  }
  Serial.print("joined ");
  Serial.println(WiFi.localIP());

  /*
   * A subscription is to a name, not to a device: the sensor keeps publishing
   * whether or not this sketch is listening, and the broker hands over the
   * latest reading straight away (it is retained).
   */
  Serial.print("subscribed ");
  Serial.println(net.subscribe("readings/temp"));

  /*
   * A network program is usually both directions: this one listens for the
   * feed, and tells the sensor how often it wants it. Publishing has no
   * audience on a bench with one board, so the network's own sensor takes the
   * order -- ask for two seconds and the feed slows to one reading every two.
   */
  Serial.print("asked for 2s ");
  Serial.println(net.publish("commands/interval", "2"));
}

void loop() {
  /*
   * No waiting: asking whether there is news and carrying on is what lets a
   * program do two things at once. The clock's loop could afford to block
   * because it had one job; this one has a screen to keep alive.
   */
  if (net.available()) {
    tft.fillRect(20, 100, 440, 60, BLACK);
    tft.print(net.message(), 20, 100, GREEN);
    Serial.print("temp ");
    Serial.println(net.message());
  }
  delay(100);
}

