#include <Arduino.h>
#include <Wire.h>

// An instrument bench: a barometer, a current monitor and a sixteen-bit
// converter, all three answering on the same two wires.
//
// The barometer speaks the register protocol rather than a library, so the
// compensation the datasheet prints is here in the sketch: the raw counts
// come off the chip, and the eleven coefficients in its E2PROM are what turn
// them into pascals and degrees.

byte BAROMETER = 0x77;
byte MONITOR = 0x40;
byte CONVERTER = 0x48;

// The chip's own calibration, read out of its E2PROM at startup.
int words[11];
int ac1, ac2, ac3, ac4, ac5, ac6, b1, b2, mb, mc, md;

// A register that holds two bytes, most significant first.
int readWord(int address, int register) {
  Wire.beginTransmission(address);
  Wire.write(register);
  Wire.endTransmission();
  Wire.requestFrom(address, 2);
  int high = Wire.read();
  int low = Wire.read();
  return (high << 8) | low;
}

// A signed register: the current and the shunt voltage can both be negative.
int readSignedWord(int address, int register) {
  int word = readWord(address, register);
  if (word > 32767) { word = word - 65536; }
  return word;
}

void readCalibration() {
  Wire.beginTransmission(BAROMETER);
  Wire.write(0xAA);
  Wire.endTransmission();
  Wire.requestFrom(BAROMETER, 22);
  for (int index = 0; index < 11; index++) {
    int high = Wire.read();
    int low = Wire.read();
    int word = (high << 8) | low;
    if (word > 32767) { word = word - 65536; }
    words[index] = word;
  }
  ac1 = words[0]; ac2 = words[1]; ac3 = words[2]; ac4 = words[3];
  ac5 = words[4]; ac6 = words[5]; b1 = words[6]; b2 = words[7];
  mb = words[8]; mc = words[9]; md = words[10];
}

// The raw temperature count: start a measurement, then read the two bytes it
// lands in.
int temperatureCounts() {
  Wire.beginTransmission(BAROMETER);
  Wire.write(0xF4);
  Wire.write(0x2E);
  Wire.endTransmission();
  Wire.beginTransmission(BAROMETER);
  Wire.write(0xF6);
  Wire.endTransmission();
  Wire.requestFrom(BAROMETER, 2);
  int high = Wire.read();
  int low = Wire.read();
  return (high << 8) | low;
}

// The raw pressure count: three bytes, left-aligned.
int pressureCounts() {
  Wire.beginTransmission(BAROMETER);
  Wire.write(0xF4);
  Wire.write(0x34);
  Wire.endTransmission();
  Wire.beginTransmission(BAROMETER);
  Wire.write(0xF6);
  Wire.endTransmission();
  Wire.requestFrom(BAROMETER, 3);
  int msb = Wire.read();
  int lsb = Wire.read();
  int xlsb = Wire.read();
  return ((msb << 16) | (lsb << 8) | xlsb) >> 8;
}

// The datasheet's temperature compensation, in tenths of a degree.
int compensateTemperature(int ut) {
  int x1 = ((ut - ac6) * ac5) >> 15;
  int x2 = idiv(mc << 11, x1 + md);
  int b5 = x1 + x2;
  return (b5 + 8) >> 4;
}

// The datasheet's pressure compensation, in pascals.
int compensatePressure(int up, int ut) {
  int x1 = ((ut - ac6) * ac5) >> 15;
  int x2 = idiv(mc << 11, x1 + md);
  int b6 = x1 + x2 - 4000;

  int bx1 = (b2 * ((b6 * b6) >> 12)) >> 11;
  int bx2 = (ac2 * b6) >> 11;
  int b3 = ((ac1 * 4 + bx1 + bx2) + 2) >> 2;
  int by1 = (ac3 * b6) >> 13;
  int by2 = (b1 * ((b6 * b6) >> 12)) >> 16;
  int b4 = (ac4 * (((by1 + by2 + 2) >> 2) + 32768)) >> 15;

  int b7 = (up - b3) * 50000;
  int p = idiv(b7 * 2, b4);
  int px1 = (((p >> 8) * (p >> 8)) * 3038) >> 16;
  int px2 = (-7357 * p) >> 16;
  return p + ((px1 + px2 + 3791) >> 4);
}

void setup() {
  Serial.begin(115200);
  Wire.begin();
  readCalibration();
  /*
   * The current register is only as good as the calibration the sketch
   * writes: 4096 is the datasheet's own worked example, a hundred
   * microamps a bit.
   */
  Wire.beginTransmission(MONITOR);
  Wire.write(0x05);
  Wire.write(0x10);
  Wire.write(0x00);
  Wire.endTransmission();
  Serial.println("instrument bench up");
}

void loop() {
  int ut = temperatureCounts();
  int up = pressureCounts();
  int tenths = compensateTemperature(ut);
  int pascals = compensatePressure(up, ut);

  int shunt = readSignedWord(MONITOR, 0x01);
  int busMillivolts = (readWord(MONITOR, 0x02) >> 3) * 4;
  int current = readSignedWord(MONITOR, 0x04);
  int power = readWord(MONITOR, 0x03);

  /*
   * The converter: tell it which channel to look at and how much of the
   * range to give it, then read the counts back.
   */
  Wire.beginTransmission(CONVERTER);
  Wire.write(0x01);
  Wire.write(0xC2);
  Wire.write(0x02);
  Wire.endTransmission();
  int counts = readSignedWord(CONVERTER, 0x00);

  int whole = idiv(tenths, 10);
  int fraction = tenths - whole * 10;
  if (fraction < 0) { fraction = 0 - fraction; }

  Serial.print("barometer ");
  Serial.print(idiv(pascals, 100));
  Serial.print(" hPa  temperature ");
  Serial.print(whole);
  Serial.print(".");
  Serial.print(fraction);
  Serial.println(" C");

  Serial.print("monitor ");
  Serial.print(idiv(current * 100, 1000));
  Serial.print(" mA  shunt ");
  Serial.print(idiv(shunt * 10, 1000));
  Serial.print(" mV  bus ");
  Serial.print(idiv(busMillivolts, 1000));
  Serial.print(" V  power ");
  Serial.print(power * 2);
  Serial.print(" mW  converter ");
  Serial.print(counts);
  Serial.println(" counts");

  delay(1000);
}

#include <Arduino.h>
#include <Wire.h>

// An environment bench: a light sensor, a thermometer and a temp/humidity
// sensor, all three answering on the same two wires.
//
// None of them hides behind a library. The BH1750 is commanded with a single
// byte and reports a raw count; the TMP102 is a pointer register and two
// bytes; the SHT31 wants a sixteen-bit command and returns six bytes, with a
// CRC after each measured word. Reading the datasheet is the exercise.

byte LIGHT = 0x23;
byte THERMOMETER = 0x48;
byte HUMIDITY = 0x44;

// The datasheet's CRC-8: polynomial 0x31, initial value 0xFF.
int crc8Byte(int crc, int value) {
  crc = crc ^ value;
  for (int bit = 0; bit < 8; bit++) {
    if ((crc & 0x80) != 0) {
      crc = ((crc << 1) ^ 0x31) & 0xFF;
    } else {
      crc = (crc << 1) & 0xFF;
    }
  }
  return crc;
}

int crc8(int high, int low) {
  return crc8Byte(crc8Byte(0xFF, high), low);
}

// A register that holds two bytes, most significant first.
int readWord(int address, int pointer) {
  Wire.beginTransmission(address);
  Wire.write(pointer);
  Wire.endTransmission();
  Wire.requestFrom(address, 2);
  int high = Wire.read();
  int low = Wire.read();
  return (high << 8) | low;
}

// The SHT31's single-shot command: high repeatability, no clock stretching.
// The bench answers at once; a real part needs the datasheet's conversion
// time before its frame is ready, so the delay is part of the sketch.
void startHumidityMeasurement() {
  Wire.beginTransmission(HUMIDITY);
  Wire.write(0x24);
  Wire.write(0x00);
  Wire.endTransmission();
  delay(20);
}

// A temperature in hundredths of a degree, with the sign in front.
void printHundredths(int hundredths) {
  if (hundredths < 0) {
    Serial.print("-");
    hundredths = 0 - hundredths;
  }
  int whole = idiv(hundredths, 100);
  int fraction = hundredths - whole * 100;
  Serial.print(whole);
  Serial.print(".");
  if (fraction < 10) { Serial.print("0"); }
  Serial.print(fraction);
}

void setup() {
  Serial.begin(115200);
  Wire.begin();

  // Power the light sensor on, then leave it measuring continuously at the
  // fine resolution. From here a read is a fresh conversion.
  Wire.beginTransmission(LIGHT);
  Wire.write(0x01);
  Wire.endTransmission();
  Wire.beginTransmission(LIGHT);
  Wire.write(0x10);
  Wire.endTransmission();

  Serial.println("environment bench up");
}

void loop() {
  // The BH1750's data register is two bytes, most significant first. The
  // datasheet's conversion is lux = count / 1.2.
  Wire.requestFrom(LIGHT, 2);
  int lightCounts = (Wire.read() << 8) | Wire.read();
  int lux = idiv(lightCounts * 10 + 6, 12);

  // The TMP102 reports a signed twelve-bit count left-justified across two
  // bytes: 0.0625 C a count, so shifting four bits down gives the count.
  int temperatureWord = readWord(THERMOMETER, 0x00);
  if (temperatureWord > 32767) { temperatureWord = temperatureWord - 65536; }
  int thermometerCounts = temperatureWord >> 4;
  int thermometerHundredths = idiv(thermometerCounts * 100, 16);

  // One SHT31 frame: temperature MSB, LSB, CRC, humidity MSB, LSB, CRC.
  startHumidityMeasurement();
  Wire.requestFrom(HUMIDITY, 6);
  int tMsb = Wire.read();
  int tLsb = Wire.read();
  int tCrc = Wire.read();
  int hMsb = Wire.read();
  int hLsb = Wire.read();
  int hCrc = Wire.read();

  int rawTemperature = (tMsb << 8) | tLsb;
  int rawHumidity = (hMsb << 8) | hLsb;
  // T = -45 + 175 * raw / 65535, and RH = 100 * raw / 65535. The extra half
  // divisor rounds the integer division to the nearest hundredth or tenth.
  int humidityHundredths = idiv(17500 * rawTemperature + 32767, 65535) - 4500;
  int humidityTenths = idiv(rawHumidity * 1000 + 32767, 65535);

  bool crcOk = crc8(tMsb, tLsb) == tCrc && crc8(hMsb, hLsb) == hCrc;

  Serial.print("light ");
  Serial.print(lux);
  Serial.print(" lx  tmp102 ");
  printHundredths(thermometerHundredths);
  Serial.print(" C  sht31 ");
  printHundredths(humidityHundredths);
  Serial.print(" C  humidity ");
  Serial.print(idiv(humidityTenths, 10));
  Serial.print(".");
  Serial.print(humidityTenths - idiv(humidityTenths, 10) * 10);
  Serial.print(" %  crc ");
  if (crcOk) {
    Serial.println("ok");
  } else {
    Serial.println("bad");
  }

  delay(1000);
}

#include <Arduino.h>
#include <Wire.h>

// BMP280 barometer on I2C: read chip id, start a measurement, read raw counts.
const byte SENSOR = 0x76;
const byte LED = 9;

int readRegister(byte reg) {
  Wire.beginTransmission(SENSOR);
  Wire.write(reg);
  Wire.endTransmission();
  Wire.requestFrom(SENSOR, 1);
  return Wire.available() ? Wire.read() : 0;
}

int readWord(byte reg) {
  Wire.beginTransmission(SENSOR);
  Wire.write(reg);
  Wire.endTransmission();
  Wire.requestFrom(SENSOR, 2);
  return (Wire.read() << 8) | Wire.read();
}

int readThreeBytes(byte reg) {
  Wire.beginTransmission(SENSOR);
  Wire.write(reg);
  Wire.endTransmission();
  Wire.requestFrom(SENSOR, 3);
  return (Wire.read() << 16) | (Wire.read() << 8) | Wire.read();
}

// Calibration words, big-endian pairs from 0x88.
int digT1, digT2, digT3;
int digP1, digP2, digP3, digP4, digP5, digP6, digP7, digP8, digP9;

void loadCalibration() {
  digT1 = readWord(0x88);
  digT2 = readWord(0x8A);
  digT3 = readWord(0x8C);
  digP1 = readWord(0x8E);
  digP2 = readWord(0x90);
  digP3 = readWord(0x92);
  digP4 = readWord(0x94);
  digP5 = readWord(0x96);
  digP6 = readWord(0x98);
  digP7 = readWord(0x9A);
  digP8 = readWord(0x9C);
  digP9 = readWord(0x9E);
}

int tFine;

int compensateTemperature(int rawT) {
  int var1 = (((rawT >> 3) - (digT1 << 1)) * digT2) >> 11;
  int var2 = (((((rawT >> 4) - digT1) * ((rawT >> 4) - digT1)) >> 12) * digT3) >> 14;
  tFine = var1 + var2;
  return (tFine * 5 + 128) >> 8;
}

int compensatePressure(int rawP) {
  int var1 = tFine - 128000;
  int var2 = var1 * var1 * digP6;
  var2 = var2 + ((var1 * digP5) << 17);
  var2 = var2 + ((digP4) << 35);
  var1 = ((var1 * var1 * digP3) >> 8) + ((var1 * digP2) << 12);
  var1 = (((1 << 47) + var1) * digP1) >> 33;
  if (var1 == 0) return 0;
  int p = 1048576 - rawP;
  p = (((p << 31) - var2) * 3125) / var1;
  var1 = (digP9 * (p >> 13) * (p >> 13)) >> 25;
  var2 = (digP8 * p) >> 19;
  p = ((p + var1 + var2) >> 8) + (digP7 << 4);
  return p / 256;
}

void setup() {
  Serial.begin(115200);
  pinMode(LED, OUTPUT);
  Wire.begin();

  Serial.print("chip id 0x");
  Serial.println(readRegister(0xD0), HEX);

  loadCalibration();
  Serial.println("bmp280 up");
}

void loop() {
  Wire.beginTransmission(SENSOR);
  Wire.write(0xF4);
  Wire.write(0x25);
  Wire.endTransmission();
  delay(100);

  int raw = readThreeBytes(0xF7);
  int rawP = raw >> 4;
  int rawT = (raw & 0x0FFFFF) >> 4;

  int temperature = compensateTemperature(rawT) / 100.0;
  int pressure = compensatePressure(rawP);

  Serial.print("temperature ");
  Serial.print(temperature);
  Serial.print(" C  pressure ");
  Serial.print(pressure);
  Serial.println(" hPa");

  digitalWrite(LED, pressure > 1010 ? HIGH : LOW);

  delay(1000);
}

