#include <Arduino.h>
#include <Wire.h>

// VL53L0X time-of-flight distance sensor on I2C. The sketch starts a
// ranging measurement, reads the distance in millimetres, and prints it.
const byte SENSOR = 0x29;
const byte LED = 9;

int readRegister(byte reg) {
  Wire.beginTransmission(SENSOR);
  Wire.write(reg);
  Wire.endTransmission();
  Wire.requestFrom(SENSOR, 1);
  return Wire.available() ? Wire.read() : 0;
}

int readDistance() {
  Wire.beginTransmission(SENSOR);
  Wire.write(0x14);
  Wire.endTransmission();
  Wire.requestFrom(SENSOR, 2);
  if (Wire.available() >= 2) {
    return (Wire.read() << 8) | Wire.read();
  }
  return 0;
}

void setup() {
  Serial.begin(115200);
  pinMode(LED, OUTPUT);
  Wire.begin();

  Serial.print("chip id 0x");
  Serial.println(readRegister(0x00), HEX);

  // Start a ranging measurement.
  Wire.beginTransmission(SENSOR);
  Wire.write(0x00);
  Wire.write(0x01);
  Wire.endTransmission();

  Serial.println("vl53l0x up");
}

void loop() {
  // Restart the measurement.
  Wire.beginTransmission(SENSOR);
  Wire.write(0x00);
  Wire.write(0x01);
  Wire.endTransmission();
  delay(50);

  int distance = readDistance();

  Serial.print("distance ");
  Serial.print(distance);
  Serial.println(" mm");

  // The light comes on within one metre.
  digitalWrite(LED, distance > 0 && distance < 1000 ? HIGH : LOW);

  delay(500);
}

