// BME280 environment sensor on I2C: temperature, pressure and humidity.
// Read chip id, start a measurement, read raw counts.
const byte SENSOR = 0x76;
const byte LED = 9;

int readRegister(byte reg) {
  Wire.beginTransmission(SENSOR);
  Wire.write(reg);
  Wire.endTransmission();
  Wire.requestFrom(SENSOR, 1);
  return Wire.available() ? Wire.read() : 0;
}

int readWord(byte reg) {
  Wire.beginTransmission(SENSOR);
  Wire.write(reg);
  Wire.endTransmission();
  Wire.requestFrom(SENSOR, 2);
  return (Wire.read() << 8) | Wire.read();
}

void setup() {
  Serial.begin(115200);
  pinMode(LED, OUTPUT);
  Wire.begin();

  Serial.print("chip id 0x");
  Serial.println(readRegister(0xD0), HEX);

  // Start a forced measurement: humidity x1, pressure/temp x1.
  Wire.beginTransmission(SENSOR);
  Wire.write(0xF2);
  Wire.write(0x01);
  Wire.endTransmission();

  Wire.beginTransmission(SENSOR);
  Wire.write(0xF4);
  Wire.write(0x25);
  Wire.endTransmission();

  Serial.println("bme280 up");
}

void loop() {
  // Restart measurement.
  Wire.beginTransmission(SENSOR);
  Wire.write(0xF2);
  Wire.write(0x01);
  Wire.endTransmission();

  Wire.beginTransmission(SENSOR);
  Wire.write(0xF4);
  Wire.write(0x25);
  Wire.endTransmission();
  delay(100);

  // Read 8 bytes: pressure (3), temperature (3), humidity (2).
  Wire.beginTransmission(SENSOR);
  Wire.write(0xF7);
  Wire.endTransmission();
  Wire.requestFrom(SENSOR, 8);

  int rawP = 0;
  int rawT = 0;
  int rawH = 0;
  if (Wire.available() >= 8) {
    rawP = (Wire.read() << 12) | (Wire.read() << 4) | (Wire.read() >> 4);
    rawT = ((Wire.read() & 0x0F) << 12) | (Wire.read() << 4) | (Wire.read() >> 4);
    rawH = (Wire.read() << 8) | Wire.read();
  }

  Serial.print("raw temp ");
  Serial.print(rawT);
  Serial.print(" raw press ");
  Serial.print(rawP);
