  Wire.begin();

  Serial.print("chip id 0x");
  Serial.println(readRegister(0x92), HEX);

  // Enable: gesture, proximity and ALS.
  Wire.beginTransmission(SENSOR);
  Wire.write(0x80);
  Wire.write(0x1D);
  Wire.endTransmission();

  Serial.println("apds9960 up");
}

void loop() {
  Wire.beginTransmission(SENSOR);
  Wire.write(0x8C);
  Wire.endTransmission();
  Wire.requestFrom(SENSOR, 1);
  int proximity = Wire.available() ? Wire.read() : 0;

  Wire.beginTransmission(SENSOR);
  Wire.write(0x8D);
  Wire.endTransmission();
  Wire.requestFrom(SENSOR, 2);
  int ambient = 0;
  if (Wire.available() >= 2) {
    ambient = (Wire.read() << 8) | Wire.read();
  }

  Wire.beginTransmission(SENSOR);
  Wire.write(0x93);
  Wire.endTransmission();
  Wire.requestFrom(SENSOR, 1);
  int gesture = Wire.available() ? Wire.read() : 0;

  Serial.print("proximity ");
  Serial.print(proximity);
  Serial.print(" ambient ");
  Serial.print(ambient);
  Serial.print(" gesture ");
  Serial.println(gesture);

  digitalWrite(LED, proximity > 200 ? HIGH : LOW);

  delay(500);
}

#include <Arduino.h>
#include <Wire.h>

// BNO055 absolute orientation sensor on I2C: heading, pitch and roll.
// Put the sensor in NDOF mode and read the orientation registers.
const byte SENSOR = 0x28;
const byte LED = 9;

int readRegister(byte reg) {
  Wire.beginTransmission(SENSOR);
  Wire.write(reg);
  Wire.endTransmission();
  Wire.requestFrom(SENSOR, 1);
  return Wire.available() ? Wire.read() : 0;
}

int readWord(byte reg) {
  Wire.beginTransmission(SENSOR);
  Wire.write(reg);
  Wire.endTransmission();
  Wire.requestFrom(SENSOR, 2);
  if (Wire.available() >= 2) {
    return (Wire.read() << 8) | Wire.read();
  }
  return 0;
}

void setup() {
  Serial.begin(115200);
  pinMode(LED, OUTPUT);
  Wire.begin();

  Serial.print("chip id 0x");
  Serial.println(readRegister(0x00), HEX);

  // NDOF mode.
  Wire.beginTransmission(SENSOR);
  Wire.write(0x3D);
  Wire.write(0x0C);
  Wire.endTransmission();

  Serial.println("bno055 up");
}

void loop() {
  int heading = readWord(0x1A);
  int pitch = readWord(0x1E);
  if (pitch > 32767) pitch = pitch - 65536;
  int roll = readWord(0x20);
  if (roll > 32767) roll = roll - 65536;

  Serial.print("heading ");
  Serial.print(heading);
  Serial.print(" pitch ");
  Serial.print(pitch);
  Serial.print(" roll ");
  Serial.println(roll);

  digitalWrite(LED, heading > 5000 ? HIGH : LOW);

  delay(500);
}

#include <Arduino.h>

// ADXL335 analog accelerometer on A0, A1 and A2. X, Y and Z are voltages:
// the mid-rail at rest, near the rail at full scale. The sketch converts
// the ADC counts back to g.
const byte X_PIN = A0;
const byte Y_PIN = A1;
const byte Z_PIN = A2;
const byte LED = 9;

void setup() {
  Serial.begin(115200);
  pinMode(LED, OUTPUT);
  Serial.println("adxl335 up");
}

int readG(byte pin) {
  int count = analogRead(pin);
  int millivolts = count * 5000 / 1024;
  // Half the supply at zero g, so subtract mid-rail and scale: 1 g is 1/6 of 5 V.
  int g = (millivolts - 2500) * 6 / 5000;
  return g;
}

void loop() {
  int x = readG(X_PIN);
  int y = readG(Y_PIN);
  int z = readG(Z_PIN);

  Serial.print("x ");
  Serial.print(x);
  Serial.print(" y ");
  Serial.print(y);
  Serial.print(" z ");
  Serial.println(z);

  // The light comes on when the tilt on X is strong.
  digitalWrite(LED, x > 1 ? HIGH : LOW);

  delay(500);
}

#include <Arduino.h>

// MQ-2 gas sensor on A0. The sensor outputs a voltage proportional to gas
// concentration: 0 V at 0 ppm, 2.5 V at 500 ppm, 5 V at 1000 ppm. The sketch
// converts the ADC count back to ppm and prints it. A light comes on when the
// concentration rises above 400 ppm.
const byte SENSOR = A0;
const byte LED = 9;

void setup() {
  Serial.begin(115200);
  pinMode(LED, OUTPUT);
  Serial.println("mq2 up");
}

int readPpm(byte pin) {
  int count = analogRead(pin);
  int millivolts = count * 5000 / 1024;
  int ppm = millivolts * 1000 / 5000;
  return ppm;
}

void loop() {
  int ppm = readPpm(SENSOR);

  Serial.print("gas ");
  Serial.print(ppm);
  Serial.println(" ppm");

  digitalWrite(LED, ppm > 400 ? HIGH : LOW);

  delay(500);
}
